        string constructorGuard = isGuid ? string.Empty : "global::System.ArgumentOutOfRangeException.ThrowIfNegative(value);";

        return new StringBuilder(Template)
            .Replace("$NAMESPACE_OPEN$", model.Namespace is null ? string.Empty : $"namespace {model.Namespace}\n{{")
            .Replace("$NAMESPACE_CLOSE$", model.Namespace is null ? string.Empty : "}")
            .Replace("$TYPE$", fullType)
            .Replace("$DISPLAYNAME$", model.DisplayName)
            .Replace("$NAME$", model.Name)
            .Replace("$CTOR_GUARD$", constructorGuard)
            .Replace("$VALUE$", isGuid ? "global::System.Guid" : "long")
